    function zoneMarkup(key) { var zone = zones[key], active = state.zone === key; return '<button class="farm-zone farm-zone--' + zone.color + (active ? ' is-active' : '') + '" type="button" data-farm-zone="' + key + '"><span class="farm-zone__crop">' + (key === 'A' ? '🍅' : key === 'B' ? '🥬' : '🥒') + '</span><span><b>' + zone.name + '</b><small>Ẩm đất ' + zone.soil + '% · Sức khỏe ' + zone.health + '%</small></span><i>' + (active ? 'Đang xem' : 'Mở khu') + '</i></button>'; }
