    function telemetryMarkup() { return state.history.map(function (value, index) { return '<div class="farm-telemetry-bar" title="Mốc ' + (index + 1) + ': ' + value + '%"><i style="height:' + Math.max(8, value) + '%"></i><span>' + (index + 1) + '</span></div>'; }).join(''); }
