    function buildAlerts() { var alerts = []; if (state.tank < 25) alerts.push({ tone: 'danger', icon: '!', text: 'Bể nước sắp cạn — cần bổ sung trước ngày mai.' }); if (zones.C.soil < 42) alerts.push({ tone: 'warn', icon: '!', text: 'Khu C đang khô — độ ẩm dưới ngưỡng khuyến nghị.' }); if (state.temp > 31) alerts.push({ tone: 'warn', icon: '!', text: 'Nhiệt độ cao — quạt thông gió đang hỗ trợ.' }); if (!alerts.length) alerts.push({ tone: 'ok', icon: '✓', text: state.lastEvent }); return alerts; }
    function tick() { state.day += 1; var heat = Math.round(Math.sin(state.day / 2) * 2); var incidentHeat = state.incident === 'heat' ? 5 : 0; var outage = state.incident === 'outage'; state.temp = 28 + heat + incidentHeat + (state.fan && !outage ? -1 : 1); state.airHumidity = pct(62 - heat * 2 - incidentHeat + (state.fan && !outage ? -1 : 0)); state.fillPump = false; if (state.fillAuto && state.tank < state.tankMin && !outage) { state.tank = pct(state.tank + 25); state.fillPump = true; state.lastEvent = 'Bơm cấp đã tự động nạp thêm 25% nước vào bể.'; } Object.keys(zones).forEach(function (key) { var zone = zones[key]; if (state.pump && state.tank > 0 && !outage) { zone.soil = pct(zone.soil + (key === state.zone ? 5 : 2)); state.tank = pct(state.tank - 3); } else { zone.soil = pct(zone.soil - (key === state.zone ? 2 : 1)); } var ideal = zone.soil >= state.soilMin && zone.soil <= 70; zone.health = pct(zone.health + (ideal ? 1 : -2)); zone.harvest = Math.max(1, zone.harvest - 1); }); if (outage) { state.pump = false; state.fan = false; state.lastEvent = 'Mất điện: thiết bị đã chuyển sang trạng thái an toàn.'; } else if (state.auto && zones[state.zone].soil < state.soilMin) { state.pump = true; state.lastEvent = 'Tự động tưới ' + zones[state.zone].name + '.'; } else if (state.auto && zones[state.zone].soil > 70) { state.pump = false; state.lastEvent = 'Đã dừng bơm để tránh tưới quá mức.'; } else if (!state.fillPump) { state.lastEvent = 'Mô hình đã tiến tới ngày ' + state.day + '.'; } state.history.push(zones[state.zone].soil); state.history = state.history.slice(-12); state.energy = Number((state.energy + (state.pump ? .8 : .2) + (state.fan ? .3 : .05) + (state.fillPump ? .5 : 0)).toFixed(1)); state.alerts = buildAlerts(); render(); }
    function bind() { workspace.querySelectorAll('[data-farm-zone]').forEach(function (button) { button.addEventListener('click', function () { state.zone = button.dataset.farmZone; render(); }); }); workspace.querySelector('[data-farm-run]').addEventListener('click', function () { state.running = !state.running; if (state.running) { timer = window.setInterval(tick, 2600); } else { window.clearInterval(timer); timer = null; } render(); setStatus(state.running ? 'Đang mô phỏng' : 'Đã tạm dừng'); }); workspace.querySelector('[data-farm-step]').addEventListener('click', function () { tick(); setStatus('Đã mô phỏng thêm 1 ngày'); }); workspace.querySelector('[data-farm-reset]').addEventListener('click', function () { window.clearInterval(timer); timer = null; state = Object.assign({}, defaultState); Object.assign(zones.A, { soil: 48, health: 86, harvest: 18 }); Object.assign(zones.B, { soil: 64, health: 92, harvest: 9 }); Object.assign(zones.C, { soil: 39, health: 74, harvest: 24 }); render(); setStatus('Đã đặt lại phiên mô phỏng'); }); workspace.querySelector('[data-farm-pump]').addEventListener('click', function () { state.pump = !state.pump; state.auto = false; state.lastEvent = state.pump ? 'Đã bật máy bơm tưới thủ công.' : 'Đã tắt máy bơm tưới thủ công.'; state.alerts = buildAlerts(); render(); setStatus('Đã cập nhật máy bơm tưới'); }); workspace.querySelector('[data-farm-refill]').addEventListener('click', function () { state.tank = pct(state.tank + 20); state.fillPump = true; state.lastEvent = 'Đã nạp thủ công thêm 20% nước vào bể.'; state.alerts = buildAlerts(); render(); setStatus('Đã nạp nước vào bể'); window.setTimeout(function () { state.fillPump = false; render(); }, 900); }); workspace.querySelector('[data-farm-fan]').addEventListener('click', function () { state.fan = !state.fan; render(); setStatus('Đã cập nhật quạt'); }); workspace.querySelector('[data-farm-auto]').addEventListener('change', function (event) { state.auto = event.target.checked; render(); setStatus(state.auto ? 'Đã bật chế độ tự động' : 'Đã tắt chế độ tự động'); }); workspace.querySelector('[data-farm-fill-auto]').addEventListener('change', function (event) { state.fillAuto = event.target.checked; render(); setStatus(state.fillAuto ? 'Đã bật tự động nạp bể dưới 25%' : 'Đã tắt tự động nạp bể'); }); workspace.querySelector('[data-farm-report]').addEventListener('click', function () { window.alert('Báo cáo minh họa\n\nSản lượng dự kiến: ' + Math.round(520 + zones[state.zone].health * 2.1) + ' kg\nNước đã dùng: ' + (state.day * 42) + ' L\nNăng lượng: ' + state.energy.toFixed(1) + ' kWh\n\nDữ liệu này chỉ dùng cho mô phỏng cục bộ.'); }); }
