    function resultFor(x, y) { if (state.dataset === 'regression') return { label: 'Ước tính ' + Math.round(120 + x * 2.1 + y * 1.4) + ' triệu', confidence: 'Sai số mô phỏng: ' + Math.max(3, Math.round(18 - x / 10)) + '%', reason: 'Giá tăng theo diện tích và điểm tiện ích.' }; if (state.dataset === 'clustering') { var cluster = x > 65 && y > 60 ? 'Cụm C' : x > 55 ? 'Cụm B' : 'Cụm A'; return { label: cluster, confidence: 'Độ gần tâm cụm: ' + Math.round(76 + Math.abs(x - y) / 4) + '%', reason: 'Điểm được gán theo khoảng cách đến tâm cụm gần nhất.' }; } var group, confidence, reason; if (state.model === 'knn') { var nearest = currentDataset().points.slice().sort(function (first, second) { return Math.hypot(first.x - x, first.y - y) - Math.hypot(second.x - x, second.y - y); })[0]; var distance = Math.hypot(nearest.x - x, nearest.y - y); group = 'Nhóm ' + nearest.group; confidence = Math.round(Math.max(55, Math.min(98, 100 - distance))); reason = group + ' vì điểm gần nhất là dữ liệu ' + nearest.group + ' ở khoảng cách ' + Math.round(distance) + '.'; } else { group = x >= 50 ? 'Nhóm B' : 'Nhóm A'; confidence = Math.round(Math.min(98, 78 + Math.abs(x - 50) / 2)); reason = group + ' vì ' + (state.model === 'tree' ? 'nút phân tách của Decision Tree' : 'ranh giới tuyến tính của Logistic Regression') + ' đặt tại Feature 1 = 50.'; } return { label: group, confidence: 'Độ tin cậy ước tính: ' + confidence + '%', reason: reason }; }
    function render() { var data = currentDataset(), result = resultFor(state.x, state.y); workspace.innerHTML = '<div class="ai-studio"><aside class="ai-sidebar"><div><p class="eyebrow">AI & Machine Learning</p><h2>Model Playground</h2><p>Chọn dataset, chọn model và quan sát kết quả thay đổi theo thời gian thực.</p></div><label class="ai-field">Dataset<select data-ai-dataset><option value="classification" ' + (state.dataset === 'classification' ? 'selected' : '') + '>Classification · 2D</option><option value="regression" ' + (state.dataset === 'regression' ? 'selected' : '') + '>Regression · giá nhà</option><option value="clustering" ' + (state.dataset === 'clustering' ? 'selected' : '') + '>Clustering · khách hàng</option></select></label><label class="ai-field">Model<select data-ai-model><option value="logistic" ' + (state.model === 'logistic' ? 'selected' : '') + '>Logistic Regression</option><option value="tree" ' + (state.model === 'tree' ? 'selected' : '') + '>Decision Tree</option><option value="knn" ' + (state.model === 'knn' ? 'selected' : '') + '>K-Nearest Neighbors</option></select></label><div class="ai-sidebar__note"><strong>' + data.title + '</strong><span>' + data.note + '</span></div><button class="button button--primary" type="button" data-ai-train ' + (state.training ? 'disabled' : '') + '>' + (state.training ? 'Đang huấn luyện ' + state.progress + '%' : 'Huấn luyện mô hình') + '</button><button class="button button--secondary" type="button" data-ai-reset>Đặt lại</button></aside><section class="ai-main"><div class="ai-toolbar"><div><strong>Training workspace</strong><span>Dataset: ' + data.points.length + ' bản ghi · Train/Test: 80/20 · Model: ' + (state.model === 'tree' ? 'Decision Tree' : state.model === 'knn' ? 'KNN' : 'Logistic Regression') + '</span></div><span class="ai-status" data-ai-status>' + (state.training ? 'Đang học epoch ' + Math.round(state.progress * 1.2) : state.trained ? 'Đã huấn luyện' : 'Sẵn sàng') + '</span></div><div class="ai-metrics" data-ai-metrics>' + metrics() + '</div><div class="ai-work-grid"><section class="ai-canvas-panel"><div class="ai-section-heading"><div><p class="eyebrow">Feature space</p><h2>' + (state.dataset === 'regression' ? 'Regression fit' : state.dataset === 'clustering' ? 'Cluster map' : 'Decision boundary') + '</h2></div><span>X: Feature 1 · Y: Feature 2</span></div><div class="ai-canvas ai-canvas--' + state.dataset + '">' + boundaryMarkup() + data.points.map(pointMarkup).join('') + (state.trained ? '<i class="ai-prediction-point" style="left:' + state.x + '%;bottom:' + state.y + '%"></i>' : '') + '<span class="ai-axis ai-axis--x">Feature 1 →</span><span class="ai-axis ai-axis--y">Feature 2 ↑</span><span class="ai-canvas-hint">' + (state.training ? 'Đang cập nhật ranh giới…' : 'Thay đổi dataset/model rồi huấn luyện lại') + '</span></div><div class="ai-legend"><span><i class="ai-dot ai-dot--a"></i> Nhóm A</span><span><i class="ai-dot ai-dot--b"></i> Nhóm B</span><span>' + (state.trained ? 'Mô hình đã học' : 'Chưa huấn luyện') + '</span></div></section><aside class="ai-inspector"><p class="eyebrow">Prediction</p><h2>Dự đoán điểm mới</h2><p>Di chuyển hai feature để xem điểm mới phản hồi.</p><label class="ai-field">Feature 1 <output data-ai-x-output>' + state.x + '</output><input type="range" min="0" max="100" value="' + state.x + '" data-ai-x></label><label class="ai-field">Feature 2 <output data-ai-y-output>' + state.y + '</output><input type="range" min="0" max="100" value="' + state.y + '" data-ai-y></label><button class="button button--primary" type="button" data-ai-predict>Dự đoán</button><div class="ai-prediction"><span>Kết quả</span><strong data-ai-prediction>' + (state.trained ? result.label : state.prediction) + '</strong><small data-ai-confidence>' + (state.trained ? result.confidence : 'Huấn luyện mô hình trước khi dự đoán.') + '</small></div><div class="ai-explanation"><p class="eyebrow">Explainability</p><strong data-ai-explanation>' + (state.trained ? result.reason : 'Kết quả sẽ được giải thích sau khi huấn luyện.') + '</strong></div></aside></div><section class="ai-results"><div class="ai-section-heading"><div><p class="eyebrow">Evaluation</p><h2>' + (state.dataset === 'clustering' ? 'Cluster summary' : 'Confusion matrix') + '</h2></div><span>Test set · local simulation</span></div><div class="ai-matrix"><div></div><b>Predicted A</b><b>Predicted B</b><strong>Actual A</strong><span>' + (state.trained ? '4' : '—') + '</span><span>' + (state.trained ? '1' : '—') + '</span><strong>Actual B</strong><span>' + (state.trained ? '0' : '—') + '</span><span>' + (state.trained ? '5' : '—') + '</span></div></section></section></div>'; bind(); }
    function train() { window.clearInterval(trainTimer); state.training = true; state.trained = false; state.progress = 0; state.prediction = 'Đang chờ mô hình'; render(); setStatus('Đang huấn luyện mô hình'); trainTimer = window.setInterval(function () { state.progress += 20; if (state.progress >= 100) { state.progress = 100; state.training = false; state.trained = true; state.accuracy = state.dataset === 'regression' ? 86 : state.dataset === 'clustering' ? 78 : state.model === 'tree' ? 92 : state.model === 'knn' ? 86 : 90; window.clearInterval(trainTimer); setStatus('Đã huấn luyện ' + currentDataset().title); } render(); }, 420); window.__intelexAiTimer = trainTimer; }
