    workspace.innerHTML = '<div class="database-studio"><aside class="database-schema"><p class="eyebrow">Schema Explorer</p><h2>Cơ sở dữ liệu mẫu</h2><p class="database-schema__lead">Chọn bảng để xem cấu trúc và quan hệ.</p><div class="database-source-actions"><button class="button button--secondary" type="button" data-show-create>Tạo bảng</button><label class="database-csv-import">Nhập CSV<input data-database-csv type="file" accept=".csv,text/csv"><span>CSV vào bảng chọn</span></label></div><div class="database-create-form" data-create-form hidden><label>Tên bảng<input data-new-table-name placeholder="sales_2026"></label><label>Cột (phân cách dấu phẩy)<input data-new-table-columns placeholder="month, team, value"></label><button class="button button--primary" type="button" data-create-table>Tạo bảng trống</button></div><div data-schema-list></div><div class="database-relationship"><strong>Quan hệ</strong><span>customers.id → orders.customer_id</span><span>products.id → orders.product_id</span></div></aside><section class="database-workbench"><div class="database-toolbar"><div><strong>SQL Editor</strong><span>Chế độ an toàn: chỉ hỗ trợ SELECT.</span></div><div><button class="icon-button" type="button" data-format-sql>Format</button><button class="button button--primary" type="button" data-run-sql>Chạy truy vấn</button></div></div><textarea class="database-editor" data-sql-editor spellcheck="false">SELECT * FROM orders ORDER BY value DESC;</textarea><div class="query-builder"><div><p class="eyebrow">Query Builder</p><h3>Tạo truy vấn không cần SQL</h3></div><label>Bảng<select data-builder-table><option value="orders">orders</option><option value="customers">customers</option></select></label><label>Điều kiện<select data-builder-filter><option value="all">Tất cả bản ghi</option><option value="high">Chỉ số ≥ 55</option><option value="product">Nhóm Sản phẩm</option></select></label><label>Hiển thị<select data-builder-view><option value="rows">Chi tiết bản ghi</option><option value="summary">Tổng hợp theo nhóm</option></select></label><button class="button button--secondary" type="button" data-build-query>Tạo SQL</button></div><section class="database-results"><div class="data-section-heading"><div><p class="eyebrow">Query results</p><h2 data-results-title>Kết quả truy vấn</h2></div><button class="icon-button" type="button" data-chart-query>Tạo biểu đồ</button></div><p class="database-run-info" data-run-info>Sẵn sàng chạy truy vấn.</p><div class="data-table-wrap"><table><thead data-query-head></thead><tbody data-query-results></tbody></table></div></section></section><aside class="database-inspector"><p class="eyebrow">Table Inspector</p><h2 data-table-name>orders</h2><p data-table-description>Bản ghi đơn hàng và chỉ số giao dịch.</p><dl data-table-columns></dl><div class="database-tip"><strong>Thử nhanh</strong><button type="button" data-sql-example="high">Đơn giá trị cao</button><button type="button" data-sql-example="group">Doanh thu theo nhóm</button><button type="button" data-sql-example="join">JOIN khách hàng</button></div><div class="database-practice"><p class="eyebrow">SQL Practice</p><strong data-practice-task>Viết truy vấn tìm đơn có chỉ số từ 55 trở lên.</strong><select data-practice-select><option value="high">WHERE</option><option value="group">GROUP BY</option><option value="join">JOIN</option></select><button class="button button--secondary" type="button" data-check-practice>Kiểm tra bài làm</button><span data-practice-feedback></span></div></aside></div>';
    function schemaTitle(name) { return name === 'orders' ? 'Đơn hàng' : name === 'customers' ? 'Khách hàng' : 'Sản phẩm'; }
    function renderSchema() { var names = Object.keys(schema); workspace.querySelector('[data-schema-list]').innerHTML = names.map(function (name) { return '<button class="database-table' + (name === activeTable ? ' is-active' : '') + '" type="button" data-schema-table="' + name + '"><strong>▦ ' + name + '</strong><span>' + schema[name].length + ' cột · ' + (tableData[name] || []).length + ' dòng</span></button>'; }).join(''); workspace.querySelector('[data-builder-table]').innerHTML = names.map(function (name) { return '<option value="' + escapeHtml(name) + '">' + escapeHtml(name) + '</option>'; }).join(''); workspace.querySelectorAll('[data-schema-table]').forEach(function (button) { button.addEventListener('click', function () { activeTable = button.dataset.schemaTable; renderSchema(); renderInspector(); }); }); }
    function renderInspector() { var descriptions = { orders: 'Bản ghi đơn hàng và chỉ số giao dịch.', customers: 'Thông tin khách hàng dùng để JOIN với đơn hàng.', products: 'Danh mục sản phẩm minh họa cho quan hệ dữ liệu.' }; workspace.querySelector('[data-table-name]').textContent = activeTable; workspace.querySelector('[data-table-description]').textContent = descriptions[activeTable] || 'Bảng do bạn tạo trong phiên làm việc này.'; workspace.querySelector('[data-table-columns]').innerHTML = schema[activeTable].map(function (column, index) { return '<div><dt>' + escapeHtml(column) + '</dt><dd>' + (index === 0 ? 'PRIMARY KEY' : /_id$/.test(column) ? 'FOREIGN KEY' : /value|price|amount|total|quantity|score/i.test(column) ? 'NUMBER' : 'TEXT') + '</dd></div>'; }).join(''); }
    function parseCsvLine(line, separator) { var cells = [], cell = '', quoted = false; for (var index = 0; index < line.length; index += 1) { var character = line[index]; if (character === '"') { if (quoted && line[index + 1] === '"') { cell += '"'; index += 1; } else quoted = !quoted; } else if (character === separator && !quoted) { cells.push(cell.trim()); cell = ''; } else cell += character; } cells.push(cell.trim()); return cells; }
    function normalizeColumn(value, index) { var name = String(value || '').trim().toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/[^a-z0-9]+/g, '_').replace(/^_|_$/g, ''); return name || 'column_' + (index + 1); }
    function importCsv(text) { var lines = text.replace(/^\uFEFF/, '').split(/\r?\n/).filter(function (line) { return line.trim(); }); if (lines.length < 2) return []; var separator = lines[0].indexOf(';') > -1 ? ';' : ',', columns = parseCsvLine(lines[0], separator).map(normalizeColumn); schema[activeTable] = columns; return lines.slice(1).map(function (line) { var cells = parseCsvLine(line, separator), row = {}; columns.forEach(function (column, index) { var value = cells[index] || ''; var numeric = Number(value.replace(/\s/g, '').replace(',', '.')); row[column] = value !== '' && Number.isFinite(numeric) ? numeric : value; }); return row; }); }
    function makeRows(query) {
      var normalized = query.toLowerCase().replace(/\s+/g, ' ').trim();
      if (!/^select\b/.test(normalized)) return { error: 'Chỉ SELECT được phép trong Database Lab.' };
      if (/\b(insert|update|delete|drop|alter|create|truncate)\b/.test(normalized)) return { error: 'Truy vấn thay đổi dữ liệu đã bị chặn để đảm bảo an toàn.' };
      var sourceMatch = normalized.match(/from\s+([a-z_][a-z0-9_]*)/), sourceTable = sourceMatch && sourceMatch[1], isCustomers = sourceTable === 'customers', isJoin = /\bjoin\b/.test(normalized), isGroup = /group by/.test(normalized), minMatch = normalized.match(/value\s*>=\s*(\d+)/), rows = (tableData[sourceTable] || []).map(function (row) { return Object.assign({}, row); });
      if (!sourceTable || !schema[sourceTable]) return { error: 'Không tìm thấy bảng trong mệnh đề FROM.' };
      if (minMatch) rows = rows.filter(function (row) { return row.value >= Number(minMatch[1]); });
      if (/team\s*=\s*['"]?sản phẩm/.test(normalized) || /team\s*=\s*['"]?san pham/.test(normalized)) rows = rows.filter(function (row) { return row.team === 'Sản phẩm'; });
      if (isJoin) rows = orders.map(function (row) { return { id: row.id, customer: row.customer, segment: customers.filter(function (customer) { return customer.id === row.customerId; })[0].segment, value: row.value }; });
      if (isGroup) { var grouped = rows.reduce(function (result, row) { var key = row.team || row.segment || 'Khác'; result[key] = (result[key] || 0) + (Number(row.value) || 1); return result; }, {}); rows = Object.keys(grouped).map(function (key) { return { group: key, total_value: grouped[key] }; }); }
      if (/order by value desc|order by total_value desc/.test(normalized)) rows.sort(function (a, b) { return (b.value || b.total_value || 0) - (a.value || a.total_value || 0); });
      var limitMatch = normalized.match(/limit\s+(\d+)/); if (limitMatch) rows = rows.slice(0, Number(limitMatch[1]));
      return { rows: rows, title: isGroup ? 'Tổng hợp theo nhóm' : isJoin ? 'Đơn hàng kết hợp khách hàng' : isCustomers ? 'Danh sách khách hàng' : 'Danh sách đơn hàng' };
    }
    function runQuery() { var result = makeRows(workspace.querySelector('[data-sql-editor]').value); if (result.error) { workspace.querySelector('[data-run-info]').textContent = result.error; workspace.querySelector('[data-query-head]').innerHTML = ''; workspace.querySelector('[data-query-results]').innerHTML = ''; setStatus('Truy vấn không hợp lệ'); return; } var columns = result.rows.length ? Object.keys(result.rows[0]) : [], elapsed = (8 + result.rows.length * 3); workspace.querySelector('[data-results-title]').textContent = result.title; workspace.querySelector('[data-run-info]').textContent = result.rows.length + ' dòng trả về · ' + elapsed + ' ms · xử lý cục bộ'; workspace.querySelector('[data-query-head]').innerHTML = '<tr>' + columns.map(function (column) { return '<th>' + escapeHtml(column) + '</th>'; }).join('') + '</tr>'; workspace.querySelector('[data-query-results]').innerHTML = result.rows.map(function (row) { return '<tr>' + columns.map(function (column) { return '<td>' + escapeHtml(row[column]) + '</td>'; }).join('') + '</tr>'; }).join('') || '<tr><td>Không có bản ghi phù hợp.</td></tr>'; workspace.querySelector('[data-chart-query]').dataset.chartValues = JSON.stringify(result.rows.map(function (row) { return Number(row.value || row.total_value); }).filter(Number.isFinite)); setStatus(result.rows.length + ' dòng trả về'); }
    function buildQuery() { var table = workspace.querySelector('[data-builder-table]').value, filter = workspace.querySelector('[data-builder-filter]').value, view = workspace.querySelector('[data-builder-view]').value, where = filter === 'high' ? ' WHERE value >= 55' : filter === 'product' ? " WHERE team = 'Sản phẩm'" : '', sql = view === 'summary' && table === 'orders' ? 'SELECT team, SUM(value) AS total_value FROM orders' + where + ' GROUP BY team ORDER BY total_value DESC;' : 'SELECT * FROM ' + table + where + (table === 'orders' ? ' ORDER BY value DESC;' : ';'); workspace.querySelector('[data-sql-editor]').value = sql; runQuery(); }
    var examples = { high: 'SELECT * FROM orders WHERE value >= 55 ORDER BY value DESC;', group: 'SELECT team, SUM(value) AS total_value FROM orders GROUP BY team ORDER BY total_value DESC;', join: 'SELECT orders.id, customers.name, orders.value FROM orders JOIN customers ON orders.customer_id = customers.id ORDER BY value DESC;' };
    renderSchema(); renderInspector(); runQuery();
    workspace.querySelector('[data-run-sql]').addEventListener('click', runQuery); workspace.querySelector('[data-build-query]').addEventListener('click', buildQuery);
    workspace.querySelector('[data-format-sql]').addEventListener('click', function () { var editor = workspace.querySelector('[data-sql-editor]'); editor.value = editor.value.replace(/\s+/g, ' ').replace(/\b(select|from|where|group by|order by|limit|join|on|sum)\b/gi, function (keyword) { return keyword.toUpperCase(); }).trim(); });
    workspace.querySelectorAll('[data-sql-example]').forEach(function (button) { button.addEventListener('click', function () { workspace.querySelector('[data-sql-editor]').value = examples[button.dataset.sqlExample]; runQuery(); }); });
    workspace.querySelector('[data-show-create]').addEventListener('click', function () { var form = workspace.querySelector('[data-create-form]'); form.hidden = !form.hidden; });
    workspace.querySelector('[data-create-table]').addEventListener('click', function () { var rawName = workspace.querySelector('[data-new-table-name]').value, rawColumns = workspace.querySelector('[data-new-table-columns]').value, name = normalizeColumn(rawName, 0), columns = rawColumns.split(',').map(function (column, index) { return column.trim() ? normalizeColumn(column, index) : ''; }).filter(Boolean); if (!rawName.trim() || !columns.length) { setStatus('Nhập tên bảng và ít nhất một cột'); return; } if (schema[name]) { setStatus('Tên bảng đã tồn tại'); return; } schema[name] = columns; tableData[name] = []; activeTable = name; workspace.querySelector('[data-create-form]').hidden = true; workspace.querySelector('[data-new-table-name]').value = ''; workspace.querySelector('[data-new-table-columns]').value = ''; renderSchema(); renderInspector(); workspace.querySelector('[data-sql-editor]').value = 'SELECT * FROM ' + name + ';'; runQuery(); setStatus('Đã tạo bảng ' + name); });
