    var practiceTasks = { high: 'Viết SELECT từ orders, lọc chỉ số từ 55 trở lên.', group: 'Tính tổng chỉ số theo team bằng GROUP BY.', join: 'Kết hợp orders và customers bằng JOIN.' };
    workspace.querySelector('[data-practice-select]').addEventListener('change', function () { workspace.querySelector('[data-practice-task]').textContent = practiceTasks[this.value]; workspace.querySelector('[data-practice-feedback]').textContent = ''; });
    workspace.querySelector('[data-check-practice]').addEventListener('click', function () { var mode = workspace.querySelector('[data-practice-select]').value, sql = workspace.querySelector('[data-sql-editor]').value.toLowerCase(), correct = mode === 'high' ? /select[\s\S]*from\s+orders[\s\S]*where[\s\S]*value\s*>=\s*55/.test(sql) : mode === 'group' ? /select[\s\S]*sum\s*\([\s\S]*from\s+orders[\s\S]*group by\s+team/.test(sql) : /from\s+orders[\s\S]*join\s+customers/.test(sql); workspace.querySelector('[data-practice-feedback]').textContent = correct ? '✓ Chính xác — bạn đã dùng đúng cấu trúc.' : 'Chưa đúng. Dùng gợi ý “Thử nhanh” hoặc kiểm tra lại mệnh đề SQL.'; workspace.querySelector('[data-practice-feedback]').classList.toggle('is-correct', correct); });
